var DeviceHealth = function DeviceHealth(user_id) {

    this.user_id = user_id;

    this.labels = this.getMetricLabelMaps();

};

DeviceHealth.TN_CONFIG = 'x_mukl_dh_config';

//------------------------------------------------
// Static functions (Inbound REST handlers)
//------------------------------------------------

/**
 * Provide the set of dex scores for the current logged in user
 *
 * @param {sn_ws_int.RESTAPIRequest} -request,
 * @param {sn_ws_int.RESTAPIResponse} - response
 */
DeviceHealth.provideDexScores = function provideDexScores(request, response) {

    var user, resp = {
        status: 200,
        data: {}
    };

    user = new dhUser();
    resp.data = user.getMetricItems();

    response.setStatus(resp.status);
    response.setContentType('application/json');

    var writer = response.getStreamWriter();
    writer.writeString(JSON.stringify(resp));
};

/**
 * Provide the set of metric ratings for each requested device
 *
 * @param {sn_ws_int.RESTAPIRequest} -request,
 * @param {sn_ws_int.RESTAPIResponse} - response
 */
DeviceHealth.provideDeviceMetrics = function provideDeviceMetrics(request, response) {

    var user;
    var resp = {
        status: 200,
        data: {}
    };

    user = new dhUser();
    resp.data = user.getDeviceMetrics();

    response.setStatus(resp.status);
    response.setContentType('application/json');

    var writer = response.getStreamWriter();
    writer.writeString(JSON.stringify(resp));
};

/**
 * Provide the set of metric values for the country of the user
 *
 * @param {sn_ws_int.RESTAPIRequest} -request,
 * @param {sn_ws_int.RESTAPIResponse} - response
 */
DeviceHealth.provideCountryMetrics = function provideCountryMetrics(request, response) {

    var user;
    var resp = {
        status: 200,
        data: {}
    };

    user = new dhUser();
    resp.data = user.getCountryMetrics();

    response.setStatus(resp.status);
    response.setContentType('application/json');

    var writer = response.getStreamWriter();
    writer.writeString(JSON.stringify(resp));
};

/**
 * Execute a remote action for a monitored device
 *
 * @param {sn_ws_int.RESTAPIRequest} -request,
 * @param {sn_ws_int.RESTAPIResponse} - response
 */
DeviceHealth.executeRemoteAction = function executeRemoteAction(request, response) {

    var action_id, asset_id;
    var user, action, device, resp;

    action_id = request.pathParams?.action_id;
    asset_id = request.pathParams?.asset_id;

    if (!action_id || !asset_id) {
        return response.setError(
            new sn_ws_err.BadRequestError('Missing action_id or asset_id path paramaters')
        );
    }

    user = new dhUser();
    action = new dhAction(action_id);
    device = user.getDevice(asset_id);

    resp = action.executeRemoteAction(device);

    if (resp.status != 200) {
        return response.setError(this.genericErrorObject(resp));
    }

    response.setStatus(resp.status);
    response.setContentType('application/json');

    delete resp.status;

    var writer = response.getStreamWriter();
    writer.writeString(JSON.stringify(resp));
};

/**
 * Executes the server script of an Action for a monitored device
 *
 * @param {sn_ws_int.RESTAPIRequest} - request,
 * @param {sn_ws_int.RESTAPIResponse} - response
 */
DeviceHealth.executeActionServerScript = function executeActionServerScript(request, response) {

    var action_id, asset_id, cache_id;
    var user, action, device, resp;
    var errorMessage;

    action_id = request.pathParams?.action_id;
    asset_id = request.pathParams?.asset_id;

    if (!action_id || !asset_id) {
        return response.setError(
            new sn_ws_err.BadRequestError('Missing action_id or asset_id path paramaters')
        );
    }

    user = new dhUser();
    action = new dhAction(action_id);
    device = user.getDevice(asset_id);

    resp = action.runServerScript(device);

    if (resp.status != 200) {

        errorMessage = resp.error.message || gs.getMessage('Script execution failed');
        gs.error('DeviceHealth.executeActionServerScript failed: ' + errorMessage + '\nAction sys_id: ' + action_id + '\nMetric Cache sys_id: ' + cache_id);

        var error = new sn_ws_err.ServiceError();
        error.setStatus(resp.status || 500);
        error.setMessage(errorMessage);
        response.setError(error);

        return;
    }

    response.setStatus(resp.status);
    response.setContentType('application/json');

    delete resp.status;

    var writer = response.getStreamWriter();
    writer.writeString(JSON.stringify(resp));
};

//------------------------------------------------
// Static functions
//------------------------------------------------

/**
 * Sends notifications to users when their DEX score is 45 or lower
 * 
 * @returns {array} information on the low DEX score entries and sent notifications
 */
DeviceHealth.sendLowDexScoreNotifications = function sendLowDexScoreNotifications() {
    try {
        var response = [];

        // Check if low DEX scores were generated in the past 2 hours
        var dexScoreQuery = 'type=DEX^dex_score<=45^userISNOTEMPTY^sys_created_onONLast 2 hours@javascript:gs.beginningOfLast2Hours()@javascript:gs.endOfLast2Hours()^ORsys_updated_onONLast 2 hours@javascript:gs.beginningOfLast2Hours()@javascript:gs.endOfLast2Hours()';

        var grDexScore = new GlideRecord('x_mukl_dh_metric_cache');
        grDexScore.addEncodedQuery(dexScoreQuery);
        grDexScore.query();

        // Check if remediation actions were run for each low DEX score and notify the users if not
        while (grDexScore.next()) {

            var payload = {};
            payload.user_name = grDexScore.getDisplayValue('user');
            payload.user_sys_id = grDexScore.getValue('user');
            payload.dex_score_record_sys_id = grDexScore.getUniqueValue();
            payload.dex_score = grDexScore.getValue('dex_score');

            // Get the user's devices/assets
            var DH = new DeviceHealth();
            var assetsArr = DH.getUserDevices(grDexScore.getValue('user'));
            var assetSysIdsArr = assetsArr.map(asset => asset.sys_id);

            payload.assets = assetsArr;

            // Check if any device remediation actions (action type = remote action, client script or server script) were run in the past 2 hours
            var actionHistoryQuery = 'metric_asset.sys_idIN' + assetSysIdsArr + '^action_typeINremote_action,client_script,server_script^splog_sys_created_onONLast 2 hours@javascript:gs.beginningOfLast2Hours()@javascript:gs.endOfLast2Hours()';

            var grActionHistory = new GlideRecord('x_mukl_dh_action_history');
            grActionHistory.addEncodedQuery(actionHistoryQuery);
            grActionHistory.setLimit(1);
            grActionHistory.query();

            // If no device remediation actions were run in the past 2 hours, send a notification to the user
            if (!grActionHistory.hasNext()) {
                gs.eventQueue('x_mukl_dh.low_dex_score', grDexScore, assetsArr);
                payload.sent_notification = true;
                // If device remediation actions were run in the past 2 hours, move on to the next user
            } else {
                payload.sent_notification = false;
            }

            response.push(payload);
        }

        return response;
    } catch (e) {
        gs.error('DeviceHealth.sendLowDexScoreNotifications failed: ' + e.message);
    }
};

DeviceHealth.aboutApplication = function aboutApplication() {

    var info = {};

    var sr = new GlideRecord('sys_scope');
    sr.get('scope',gs.getCurrentScopeName());

    if ( sr.isValidRecord() ) {
        info.app_name    = sr.name + '';
        info.app_version = sr.version + '';
    }

    sr = new GlideRecord('sys_scope');
    sr.addQuery('scope','STARTSWITH','x_mukl_')
      .addOrCondition('scope','STARTSWITH','x_teu_');
    sr.orderBy('name');
    sr.query();

    var apps  = [];
    var count = 0;

    while ( sr.next() ) {
        apps.push([sr.name,sr.scope,sr.version].join('\t'));
        count += 1;
    }

    var hdr = [
        'ServiceNow instance: ' + gs.getProperty('instance_name'),
        'Collection time: ' + new GlideDateTime(),
        '',
        'Application count: ' + count,
        '',
        'Name\tScope\tVersion'
    ];

    info.all_app_versions = hdr.join('\n') +  apps.join('\n');

    return info;

};

//------------------------------------------------
// Prototype definition
//------------------------------------------------

DeviceHealth.prototype = {
    ASSET_TABLE: gs.getProperty('x_mukl_dh.asset.table', 'alm_hardware'),
    ASSET_QUERY: gs.getProperty(
        'x_mukl_dh.asset.query',
        'assigned_toDYNAMIC90d1921e5f510100a9ad2572f2b477fe'
    ),

    type: 'DeviceHealth',
};

//------------------------------------------------
// Property methods
//------------------------------------------------

DeviceHealth.prototype.getUser = function getUser() {
    if (this.user) {
        return this.user;
    }
    this.user = new dhUser(this.user_id);
    return this.user;
};

DeviceHealth.prototype.getUserId = function getUserId() {
    return this.getUser().getId();
};

DeviceHealth.prototype.getDeviceNames = function getDeviceNames() {
    return this.getUser().getDeviceNames();
};

DeviceHealth.prototype.getDevice = function getDevice(device_name) {
    return this.getUser().getDevice(device_name);
};

//------------------------------------------------
// Actions methods
//------------------------------------------------

/**
 * @typedef ActionHistoryObj
 * @prop {string} asset - Name of asset
 * @prop {string} date - date string 'yyyy-mm-dd'
 * @prop {string} title - Title of Action
 */

/**
 *
 * @param {string[]} metricId - Array of Metric Record sys_ids
 * @returns {ActionHistoryObj[]}
 */
DeviceHealth.prototype.getActionHistory = function getActionHistory() {

    var DEX_SCORE_DAYS = parseInt(gs.getProperty('x_mukl_dh.dex.days.shown', 7));

    /**@type {ActionHistoryObj[]} */
    const act_hist = new global.GlideQuery('x_mukl_dh_action_history')
        .where('splog_sys_created_on', '>=', gs.daysAgoStart(DEX_SCORE_DAYS))
        .where('splog_sys_created_on', '<=', gs.daysAgoEnd(0))
        .where('action_type', 'remote_action')
        .where('metric_asset.assigned_to', this.getUserId())
        .select(['metric_asset.ci$DISPLAY', 'splog_sys_created_on', 'action_title'])
        .map((log) => {
            /**@type {ActionHistoryObj} */
            let obj = {
                asset: log.metric_asset?.ci$DISPLAY,
                date: log.splog_sys_created_on.split(' ')[0],
                title: log.action_title,
            };

            return obj;
        })
        .toArray(100);

    return act_hist || [];
};

/**
 * @param {string} sys_id - sys_id of the action
 * @param {Array<string>} fields - array of field names
 * @returns {Object | null}
 */
DeviceHealth.getAction = function(sys_id, fields) {
    return new global.GlideQuery('x_mukl_dh_actions')
        .get(sys_id, fields)
        .orElse(null);
};

/**
 *
 * @param {Object} error
 * @param {number} error.status
 * @param {string} error.message
 * @returns {sn_ws_err.ServiceError}
 */
DeviceHealth.genericErrorObject = function genericErrorObject(error) {

    var err = new sn_ws_err.ServiceError();
    err.setStatus(error.status);
    err.setMessage(error?.code || error?.message);

    if (error?.code && error?.message) err.setDetail(error.message);

    return err;
};

//------------------------------------------------
// Utils methods
//------------------------------------------------

DeviceHealth.prototype.userHasDevices = function userHasDevices() {
    return this.getUser().hasDevice();
};

DeviceHealth.prototype.getUserDevices = function getUserDevices(userSysId) {
    var devices = [];
    var assetQuery = (userSysId) ? 'assigned_to=' + userSysId : this.ASSET_QUERY;

    global.GlideQuery.parse(this.ASSET_TABLE, assetQuery)
        .select('ci.name')
        .forEach((device) => {
            devices.push({
                name: device?.ci?.name,
                sys_id: device.sys_id,
            });
        });

    return devices;
};

DeviceHealth.prototype.getMetricFieldLabelMaps =
    function getMetricFieldLabelMaps() {
        var fields = {};

        // Use the following GlideRecord purely as a reference to get the fields labels
        const grMetricCache = new GlideRecord('x_mukl_dh_metric_cache');

        const fieldNames = this.getRatingFieldsNames();

        fieldNames.forEach(
            (fieldName) =>
                (fields[fieldName] = grMetricCache.getElement(fieldName).getLabel())
        );

        return fields;
    };

DeviceHealth.prototype.getMetricLabelMaps =
    function getMetricLabelMaps() {
        var labels = {};

        // Use the following GlideRecord purely as a reference to get the labels
        const grCfg = new GlideRecord('x_mukl_dh_config');
        grCfg.addActiveQuery();
        grCfg.query();
        while (grCfg.next()) {
            if (!labels[grCfg.name]) {
                labels[grCfg.name] = grCfg.short_description + '';
            }
        }

        return labels;
    };

DeviceHealth.prototype.getRatingFieldsNames = function getRatingFieldsNames() {
    // Get all the elements in the sys_ui_section 'Metrics'
    var fieldNames = [];

    var elemQuery = gs.getProperty(
        'x_mukl_dh.metric.overall_score.element.query'
    );

    var grSUE = new GlideRecord('sys_ui_element');
    grSUE.addQuery(elemQuery);
    grSUE.query();

    while (grSUE.next()) {
        // Grab all the field names
        fieldNames.push(grSUE.getValue('element'));
    }

    return fieldNames;
};

//------------------------------------------------
// Original methods
//------------------------------------------------

/*
	@name             AIUserData
	@description      End point designed to be used for returning all a users context. This would allow full visibility of the users metrics and available actions to be performed.
	@returns          {Object} Object composed of 2 section. The user metrics and associated device metrics.
*/

DeviceHealth.prototype.AIUserData = function AIUserData() {
    var user = this.getUser();

    var info = {};
    info['user_metrics'] = user.getMetricItems();
    info['device_metrics'] = user.getDeviceMetrics();

    return info;

};
